# Generated by Selenium IDE
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestVesselManagement:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_vessel_management(self):
        # Authenticate as Shipping Agent
        self.driver.get("https://portide.vercel.app/login")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "email"))).send_keys("ops.india@maersk-line.com")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "password"))).send_keys("Maersk@2026")
        self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))).click()

        # Navigate to Vessel Operations Dashboard
        self.driver.get("https://portide.vercel.app/vessels")

        # Wait for vessel registry records to render
        vessel_grid = self.wait.until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ".vessel-card, .vessel-table"))
        )
        assert vessel_grid.is_displayed()

        # Submit Notice of Arrival (NOA)
        noa_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Request Arrival') or contains(., 'New Voyage')]"))
        )
        noa_btn.click()

        # Verify arrival declaration form opened
        self.wait.until(EC.presence_of_element_located((By.NAME, "eta_datetime")))
        time.sleep(2)
